script:
export const meta = {
  name: 'wayne-code-review-flow',
  description: 'Dual model-family static review of one frozen diff: freeze -> two independent voices (Claude + GPT) in parallel -> attributed synthesis -> gate. Portable across repos.',
  phases: [{ title: 'Freeze' }, { title: 'Review' }, { title: 'Synthesize' }],
};

// --- params (all optional) ---------------------------------------------------
const base = (args && args.base) ? String(args.base) : '';
const CLAUDE = (args && args.claudeModel) || 'amd-internal-anthropic/Claude-Opus-4.8';
const GPT = (args && args.gptModel) || 'openai-amd/gpt-5.6-sol';

// --- 1. Freeze the target: one immutable patch + sha256, same bytes for both -
phase('Freeze');
const freezeScript = `
set -e
base='${base}'
root="$(git rev-parse --show-toplevel)"
mkdir -p "$root/.pi"
out="$root/.pi/wcr-freeze.patch"
if [ -n "$base" ]; then
  git diff $base > "$out"
  used="$base"
else
  git diff HEAD > "$out"
  if [ ! -s "$out" ]; then
    git diff HEAD~1 HEAD > "$out"
    used="HEAD~1 HEAD (last commit; no uncommitted changes)"
  else
    used="working tree + staged vs HEAD"
  fi
fi
sha="$(sha256sum "$out" | cut -d' ' -f1)"
bytes="$(wc -c < "$out")"
printf '{"patchPath":".pi/wcr-freeze.patch","sha256":"%s","bytes":%s,"used":"%s"}\\n' "$sha" "$bytes" "$used"
`;
const freezeOut = await agent(
  `Run this EXACT bash and return ONLY the final JSON line it prints on stdout, nothing else:\n\n\`\`\`bash\n${freezeScript}\n\`\`\``,
  { model: CLAUDE, phase: 'Freeze' },
);

const jm = freezeOut.match(/\{[\s\S]*\}/);
if (!jm) return `wayne-code-review-flow: FREEZE FAILED — no JSON from freeze step.\n\n${freezeOut}`;
let frozen;
try { frozen = JSON.parse(jm[0]); } catch (e) { return `wayne-code-review-flow: FREEZE FAILED — bad JSON: ${e}\n\n${freezeOut}`; }
const bytes = Number(frozen.bytes || 0);
if (!bytes) return `wayne-code-review-flow: NOTHING TO REVIEW — empty diff (base='${base || "worktree/HEAD"}').`;
const patchPath = frozen.patchPath;
const sha = frozen.sha256;
const used = frozen.used;

// --- 2. Two heterogeneous voices, parallel, independent ----------------------
const reviewPrompt = (voice) => `You are an independent static code reviewer (voice: ${voice}).

FROZEN TARGET
- Patch file: ${patchPath}  (sha256=${sha}, diff=${used})
- Read that file with the read tool. Review ONLY the changes in this patch.
- You MAY read/grep surrounding code in the repo for evidence/context.

HARD RULES
- READ-ONLY. Do not edit, write, or run any mutating command.
- Do not guess. Every finding needs a concrete file:line and causal evidence tied to the patch.
- You have NOT seen any other reviewer's output. Judge independently.
- Severities are exactly two: CRITICAL (wrong value, exploit, corruption, contract break, reachable failure)
  or INFORMATIONAL (dead surface, maintainability, unproven risk). A claim needing runtime observation is INFORMATIONAL, marked runtime:UNVERIFIED.

OUTPUT — return ONLY this JSON object, no prose:
{
  "voice": "${voice}",
  "patch_sha256": "${sha}",
  "verdict": "NO FINDINGS" | "FINDINGS",
  "findings": [
    { "severity": "CRITICAL"|"INFORMATIONAL", "confidence": 1-10,
      "category": "security|dataflow|architecture|concurrency|performance|tests|api-migration|general",
      "file": "<repo-relative path>", "line": <number>,
      "problem": "<one sentence>", "evidence": "<concrete proof>", "fix": "<recommended change>" }
  ]
}
"NO FINDINGS" requires findings=[].`;

phase('Review');
const [claudeRaw, gptRaw] = await parallel([
  () => agent(reviewPrompt('claude'), { model: CLAUDE, phase: 'Review' }),
  () => agent(reviewPrompt('gpt'), { model: GPT, phase: 'Review' }),
]);

// --- 3. Synthesize with attribution + gate -----------------------------------
phase('Synthesize');
const synthPrompt = `You are the synthesizer for a dual-voice static review. Two INDEPENDENT reviewers of different model families examined the SAME frozen patch (sha256=${sha}).

=== VOICE A (Claude / ${CLAUDE}) RAW ===
${claudeRaw}

=== VOICE B (GPT / ${GPT}) RAW ===
${gptRaw}

TASK
1. Deduplicate by causal MECHANISM + affected behavior, not by line alone.
2. Attribute each finding: AGREEMENT (both voices independently), CLAUDE-ONLY, GPT-ONLY,
   or CONTRADICTION (mark UNRESOLVED; give both positions, pick no winner).
3. Keep original confidence; +1 (cap 10) only when dual independent evidence agrees.
4. Recompute counts from the raw artifacts. Invent nothing not present in either voice.
5. If a voice returned malformed/empty output, say so — never treat provider failure as "NO FINDINGS".

GATE
- FAIL on any unresolved CRITICAL or any CONTRADICTION affecting correctness/safety/compatibility/intent.
- PASS only with two valid voices, no unresolved blocker, consistent counts.

OUTPUT: markdown with sections Verdict, Patch, Counts (severity x source), Agreements,
Claude-only, GPT-only, Contradictions(UNRESOLVED), Runtime boundary.
End with EXACTLY one final line: "GATE: PASS" or "GATE: FAIL".`;

const report = await agent(synthPrompt, { model: CLAUDE, phase: 'Synthesize' });

const t = report.trim();
const gate = /GATE:\s*PASS\s*$/.test(t) ? 'PASS'
  : /GATE:\s*FAIL\s*$/.test(t) ? 'FAIL'
  : 'INDETERMINATE (no gate line — treat as FAIL)';
log(`wayne-code-review-flow gate: ${gate}`);

return `# wayne-code-review-flow — gate: ${gate}

Frozen: ${patchPath} (sha256=${sha})
Diff: ${used} | ${bytes} bytes
Voices: Claude=${CLAUDE} | GPT=${GPT} (parallel, independent)

${report}

---
Note: lightweight dual-family review. It does NOT carry wayne-code-review's frozen
intent packet / schema gate / drift detection — use the wayne-code-review skill when a
formal merge gate is required.`;
